package blogger

import (
	"context"
	"testing"

	"golang.org/x/oauth2"
)

func TestNewClientRejectsNilTokenSource(t *testing.T) {
	client, err := NewClient(context.Background(), nil)
	if err == nil {
		t.Fatal("NewClient(nil) returned nil error")
	}
	if client != nil {
		t.Fatalf("NewClient(nil) returned non-nil client: %+v", client)
	}
}

func TestNewClientWithoutNetwork(t *testing.T) {
	ts := oauth2.StaticTokenSource(&oauth2.Token{AccessToken: "test-token"})

	client, err := NewClient(context.Background(), ts)
	if err != nil {
		t.Fatalf("NewClient: %v", err)
	}
	if client == nil {
		t.Fatal("NewClient returned nil client")
	}
	if client.Blogger == nil {
		t.Fatal("client.Blogger is nil")
	}
}

func TestScopesCoverBloggerAPI(t *testing.T) {
	if len(Scopes) == 0 {
		t.Fatal("Scopes is empty")
	}
	for _, s := range Scopes {
		if s == "" {
			t.Error("Scopes contains an empty entry")
		}
	}
}

